head.script:
/**/(function(){
  var XHTML_NS="http://www.w3.org/1999/xhtml";
  var SVG_NS="http://www.w3.org/2000/svg";
  // Lucide-style icons render <svg>/<path>/<line>/<circle> via
  // document.createElement — without this they land in the XHTML
  // namespace as unknown elements and never paint.
  var SVG_TAGS={svg:1,path:1,line:1,circle:1,rect:1,polyline:1,polygon:1,ellipse:1,g:1,defs:1,use:1,symbol:1};
  var root=document.querySelector("foreignObject").firstElementChild;
  var origCE=document.createElement.bind(document);
  var origCENS=document.createElementNS.bind(document);
  Object.defineProperty(document,"head",{get:function(){return root.querySelector("head")},configurable:true});
  Object.defineProperty(document,"body",{get:function(){return root.querySelector("body")},configurable:true});
  Object.defineProperty(document,"documentElement",{get:function(){return root},configurable:true});
  document.createElement=function(t,o){if(typeof t==="string"){if(SVG_TAGS[t.toLowerCase()])return origCENS(SVG_NS,t,o);return origCENS(XHTML_NS,t,o)}return origCE(t,o)};
  document.createElementNS=function(ns,n,o){return (ns==null||ns===XHTML_NS)?origCENS(XHTML_NS,n,o):origCENS(ns,n,o)};
  Object.defineProperty(document,"getElementById",{value:function(id){return root.querySelector('[id="'+String(id).replace(/["\\]/g,'\\$&')+'"]')},configurable:true,writable:true});
  document.getElementsByTagName=function(t){return root.getElementsByTagNameNS(XHTML_NS,t)};
  document.getElementsByTagNameNS=function(ns,t){return root.getElementsByTagNameNS(ns,t)};
  document.getElementsByClassName=function(c){return root.getElementsByClassName(c)};
  var origQS=document.querySelector.bind(document);
  var origQSA=document.querySelectorAll.bind(document);
  document.querySelector=function(s){try{return root.querySelector(s)||origQS(s)}catch(e){return origQS(s)}};
  document.querySelectorAll=function(s){try{var a=root.querySelectorAll(s);return a.length?a:origQSA(s)}catch(e){return origQSA(s)}};
  // innerHTML in an XML document parses as XML: HTML void tags (<br>,
  // <img>, markdown output…) throw. Self-close the void set first; if the
  // markup still won't parse (entities, stray text), re-parse it as HTML
  // and adopt the nodes (same non-executing semantics as innerHTML).
  var XD=null;
  try { XD=Object.getOwnPropertyDescriptor(Element.prototype,"innerHTML"); } catch (XE2) {}
  if (XD && XD.set) {
    var XV=/^(meta|link|img|br|hr|input|source|track|wbr|col|base|area|embed|param)$/i;
    var XMAX=50000;
    var xfix=function(s) {
      s=String(s);
      if (s.length>XMAX) return s;
      return s.replace(/<([a-zA-Z][a-zA-Z0-9]*)((?:"[^"]*"|'[^']*'|[^<>"'])*)>/g, function(m,t,a) {
        if (XV.test(t) && !/\/\s*$/.test(a)) return "<"+t+a+" />";
        return m;
      });
    };
    var xset=function(el,s) {
      try { XD.set.call(el,xfix(s)); return; } catch (e1) {}
      try {
        var d=new DOMParser().parseFromString("<body>"+s+"</body>","text/html");
        var kids=[];
        var nl=d.body.childNodes;
        for (var i=0;i<nl.length;i++) kids.push(nl[i]);
        while (el.firstChild) el.removeChild(el.firstChild);
        for (var j=0;j<kids.length;j++) el.appendChild(document.adoptNode(kids[j]));
        return;
      } catch (e2) {}
      try { XD.set.call(el,""); } catch (e3) {}
    };
    try {
      Object.defineProperty(Element.prototype,"innerHTML",{
        set:function(v){ xset(this,String(v)); },
        get:function(){ return XD.get.call(this); },
        configurable:true
      });
    } catch (XE3) {}
  }
})();/**/

/**/
      // Sibling worker entry (same directory as this SVG on the mirror).
      // Registered from head so it controls the document before the app
      // bundle runs. Stale-cleanup + reload-once per deploy.
      window.__SW_FILE__ = "sw.js";
      window.__swRegistration = navigator.serviceWorker
        ? (function () {
            var FILE = (window.__SW_FILE__ || "").split("/").pop();
            var base = function (u) {
              try {
                return new URL(u, location.href).pathname.split("/").pop();
              } catch (e) {
                return String(u);
              }
            };
            var scope = new URL(".", new URL(window.__SW_FILE__, location.href)).href;
            navigator.serviceWorker
              .getRegistrations()
              .then(function (regs) {
                regs.forEach(function (r) {
                  var w = r.active || r.waiting || r.installing;
                  if (r.scope !== scope && w && base(w.scriptURL) !== FILE) r.unregister();
                });
              })
              .catch(function () {});
            return navigator.serviceWorker
              .register(window.__SW_FILE__)
              .then(function (reg) {
                function currentControls() {
                  var c = navigator.serviceWorker.controller;
                  return !!c && base(c.scriptURL) === FILE;
                }
                if (currentControls()) {
                  sessionStorage.removeItem("__sw_reload");
                  return reg;
                }
                if (sessionStorage.getItem("__sw_reload")) return reg;
                navigator.serviceWorker.ready.then(function () {
                  if (currentControls()) return;
                  var settled = false;
                  var onCtrl = function () {
                    if (!currentControls()) return;
                    settled = true;
                    navigator.serviceWorker.removeEventListener(
                      "controllerchange",
                      onCtrl
                    );
                  };
                  navigator.serviceWorker.addEventListener(
                    "controllerchange",
                    onCtrl
                  );
                  setTimeout(function () {
                    navigator.serviceWorker.removeEventListener(
                      "controllerchange",
                      onCtrl
                    );
                    if (!settled && !currentControls()) {
                      sessionStorage.setItem("__sw_reload", "1");
                      location.reload();
                    }
                  }, 1200);
                });
                return reg;
              })
              .catch(function (err) {
                console.error("[sw] registration failed:", err);
                return null;
              });
          })()
        : Promise.resolve(null);
/**/

/**/// Some deps probe process.env (guarded typeof checks,
 // but a bare reference in a classic script is fatal if ever hit).
  window.process = window.process || { env: {} };/**/
